#ifndef EMPLOYEE_CARDS_H
#define EMPLOYEE_CARDS_H
#define EMPLOYEE_CARDS_HTML "<section id='employeeCards' hidden><h2>Cards</h2><p class='muted'>Card status changes require a manager card. Earlier punches are kept.</p><p id='ec-status' role='status'></p><section><div class='table-scroll'><table><thead><tr><th>Card</th><th>Type</th><th>Status</th><th>Action</th></tr></thead><tbody id='ec-rows'></tbody></table></div></section><section id='ec-replacement' hidden><h2>Replace lost card</h2><p id='ec-target'></p><label>New card<input id='ec-newUid' maxlength='20' autocomplete='off' placeholder='Scan or enter the card UID'></label><div class='actions'><button class='secondary' type='button' id='ec-scanReplace'>Scan new card (30 seconds)</button><button type='button' id='ec-saveReplace'>Replace card</button><button type='button' class='secondary' id='ec-cancelReplace'>Cancel</button></div><p id='ec-replaceStatus' role='status'></p></section></section>"
#define EMPLOYEE_CARDS_JS "<script>(()=>{let employee=0;const status=document.getElementById('ec-status'),rows=document.getElementById('ec-rows'),replacement=document.getElementById('ec-replacement'),target=document.getElementById('ec-target'),newUid=document.getElementById('ec-newUid'),scanReplace=document.getElementById('ec-scanReplace'),saveReplace=document.getElementById('ec-saveReplace'),cancelReplace=document.getElementById('ec-cancelReplace'),replaceStatus=document.getElementById('ec-replaceStatus');let selected=null,scanTimer=null;const api=tc.api;async function refresh(){let j=await api('/api/v1/admin/card-status');rows.replaceChildren();for(let c of j.cards.filter(c=>String(c.employee_id)===String(employee))){let tr=document.createElement('tr');for(let v of [c.uid,c.kind==='manager'?'Manager':'Attendance',c.active?'Active':'']){let td=document.createElement('td');td.textContent=v;tr.append(td)}if(!c.active)tr.children[2].append(tc.flag('Inactive','muted'));let td=document.createElement('td'),b=document.createElement('button');b.className='secondary';b.textContent=c.active?'Deactivate':'Reactivate';b.onclick=()=>change(c);td.append(b);if(c.kind==='employee'&&c.active){let r=document.createElement('button');r.type='button';r.className='secondary';r.textContent='Replace';r.onclick=()=>{selected=c;replacement.hidden=false;target.textContent='Replacing '+c.uid+' for '+c.name+'. The old card stops working when you save.';newUid.value='';scanReplace.textContent='Scan new card (30 seconds)';replaceStatus.textContent='';newUid.focus()};td.append(' ',r)}tr.append(td);rows.append(tr)}}async function change(c){if(!await tc.ask({title:(c.active?'Deactivate ':'Reactivate ')+c.uid+'?',ok:c.active?'Deactivate':'Reactivate',danger:c.active}))return;status.textContent=tc.CARD;try{let approval=await api('/api/v1/admin/employee-change/arm',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:new URLSearchParams({op:'card_status',uid:c.uid,kind:c.kind,active:c.active?'0':'1'})});await tc.card('/api/v1/admin/employee-change/status',approval.token);await refresh();window.dispatchEvent(new Event('timeclock:employee-updated'));tc.ok(status,'Card '+(c.active?'deactivated.':'reactivated.'))}catch(e){tc.err(status,e)}}cancelReplace.onclick=()=>{replacement.hidden=true;selected=null;if(scanTimer)clearInterval(scanTimer)};scanReplace.onclick=async()=>{if(!selected)return;scanReplace.disabled=true;scanReplace.textContent='Scan new card (30 seconds)';replaceStatus.textContent='Tap the new card on the clock.';try{await api('/api/v1/admin/manager-scan/arm',{method:'POST'});let attempts=0;scanTimer=setInterval(async()=>{try{let j=await api('/api/v1/admin/manager-scan/status');if(j.status==='scanned'&&j.uid){newUid.value=j.uid;scanReplace.textContent=j.uid;replaceStatus.textContent='Select Replace card to save.';clearInterval(scanTimer);scanTimer=null;scanReplace.disabled=false}else if(j.status==='expired'||++attempts>48){clearInterval(scanTimer);scanTimer=null;scanReplace.disabled=false;tc.err(replaceStatus,tc.TIMEOUT)}}catch(e){clearInterval(scanTimer);scanTimer=null;scanReplace.disabled=false;tc.err(replaceStatus,e)}},700)}catch(e){scanReplace.disabled=false;tc.err(replaceStatus,e)}};saveReplace.onclick=async()=>{if(!selected)return;let newCard=newUid.value.trim().toUpperCase();if(!/^(?:[A-F0-9]{2}){4,10}$/.test(newCard)){tc.err(replaceStatus,'Enter a card UID of 8 to 20 hexadecimal characters.');return}if(!await tc.ask({title:'Replace '+selected.uid+' with '+newCard+' for '+selected.name+'?',ok:'Replace card'}))return;saveReplace.disabled=true;try{await api('/api/v1/admin/card-replace',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:new URLSearchParams({old_uid:selected.uid,new_uid:newCard})});tc.ok(replaceStatus,'Card replaced. The old card no longer works.');selected=null;await refresh();window.dispatchEvent(new Event('timeclock:employee-updated'))}catch(e){tc.err(replaceStatus,e)}finally{saveReplace.disabled=false}};window.employeeCards={open:id=>{employee=id;selected=null;replacement.hidden=true;document.getElementById('employeeCards').hidden=!id;if(id)refresh().catch(e=>tc.err(status,e))},stop:()=>{if(scanTimer)clearInterval(scanTimer);scanTimer=null;scanReplace.disabled=false}}})();</script>"
#endif
